<script setup lang="ts">
import { ref, computed } from 'vue'
import { RefreshRight, List } from '@element-plus/icons-vue'
import { useWorkspace } from '../store'
import { showError } from '../api'
import { terminal } from '../types'
import TaskCard from '../components/TaskCard.vue'
const ws = useWorkspace(), filter = ref('all'), kind = ref('all'), refreshing = ref(false)
const filtered = computed(() => ws.tasks.filter(t => (kind.value === 'all' || t.kind === kind.value) && (filter.value === 'all' || filter.value === 'active' && !terminal(t.status) || filter.value === 'attention' && ['failed', 'needs_review', 'interrupted', 'partial'].includes(t.status) || filter.value === 'done' && t.status === 'completed')))
async function refresh() { refreshing.value = true; try { await ws.refreshTasks() } catch (e) { showError(e) } finally { refreshing.value = false } }
</script>
<template><div class="tasks-page"><header class="page-heading"><div><div class="eyebrow">BACKGROUND ACTIVITY</div><h1>研究继续，进度始终可见</h1><p>获取、解析与问答在后台处理，离开页面后仍可回来看结果。</p></div><el-button :loading="refreshing" @click="refresh"><el-icon><RefreshRight/></el-icon>刷新</el-button></header><div class="task-summary"><div><span class="summary-dot running"></span><strong>{{ ws.activeTasks.length }}</strong><span>处理中与等待</span></div><div><span class="summary-dot attention"></span><strong>{{ ws.tasks.filter(t => ['needs_review', 'failed', 'interrupted'].includes(t.status)).length }}</strong><span>需要关注</span></div><div><span class="summary-dot complete"></span><strong>{{ ws.tasks.filter(t => t.status === 'completed').length }}</strong><span>已完成</span></div></div><div class="tasks-toolbar"><div class="segmented-control"><button v-for="item in [{ value: 'all', label: '全部任务' }, { value: 'active', label: '处理中与等待' }, { value: 'attention', label: '需要关注' }, { value: 'done', label: '已完成' }]" :key="item.value" :class="{ active: filter === item.value }" @click="filter = item.value">{{ item.label }}</button></div><el-select v-model="kind" aria-label="任务类型"><el-option label="全部类型" value="all"/><el-option label="文献检索" value="search"/><el-option label="获取全文" value="reading"/><el-option label="科研问答" value="answer"/><el-option label="上传入库" value="upload"/><el-option label="加入文献库" value="import"/><el-option label="索引维护" value="legacy_reindex"/></el-select></div><div v-if="!filtered.length" class="large-empty"><span class="empty-search-symbol"><el-icon><List/></el-icon></span><h2>这里暂时很安静</h2><p>开始文献检索、获取全文或上传论文后，进度将在这里显示。</p><router-link to="/discover" class="text-action">发现文献</router-link></div><div v-else class="task-list"><TaskCard v-for="task in filtered" :key="task.id" :task="task"/></div></div></template>
